// D:\PythonProject3\src\App.js

import React, { useState, useEffect } from "react";
import LoginForm from "./LoginForm";
import RegisterForm from "./RegisterForm";
import DepositForm from "./DepositForm";
import WithdrawForm from "./WithdrawForm";
import Home from "./Home";
import AdminDepositRequests from "./AdminDepositRequests";
import AdminWithdrawRequests from "./AdminWithdrawRequests";
import UserHistory from "./UserHistory";
import AdminUserHistory from "./AdminUserHistory";
import Match from "./components/Match"; // ✅ নতুন ইম্পোর্ট

function App() {
  const [token, setToken] = useState(null);
  const [email, setEmail] = useState("");
  const [role, setRole] = useState(null);
  const [showRegister, setShowRegister] = useState(false);
  const [view, setView] = useState("home");

  useEffect(() => {
    const savedToken = localStorage.getItem("authToken");
    if (savedToken) setToken(savedToken);
  }, []);

  useEffect(() => {
    const fetchUserInfo = async () => {
      if (!token) return;

      try {
        const res = await fetch("http://localhost:8080/api/user/profile", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });

        if (!res.ok) throw new Error("Failed to fetch user profile");

        const user = await res.json();
        setEmail(user.email || "");
        setRole(user.role || "");
      } catch (err) {
        console.error("User profile fetch error:", err);
        handleLogout();
      }
    };

    fetchUserInfo();
  }, [token]);

  const handleLogin = (token) => {
    localStorage.setItem("authToken", token);
    setToken(token);
    setView("home");
  };

  const handleLogout = () => {
    localStorage.removeItem("authToken");
    setToken(null);
    setEmail("");
    setRole(null);
    setView("home");
  };

  const handleRegisterSuccess = () => {
    setShowRegister(false);
  };

  const isAdmin = (role || "").toLowerCase() === "admin";

  if (!token) {
    return showRegister ? (
      <RegisterForm
        onRegisterSuccess={handleRegisterSuccess}
        goToLogin={() => setShowRegister(false)}
      />
    ) : (
      <LoginForm
        onLogin={handleLogin}
        onRegisterClick={() => setShowRegister(true)}
      />
    );
  }

  if (role === null) {
    return <p style={{ padding: "20px" }}>লোড হচ্ছে...</p>;
  }

  return (
    <div>
      {view === "home" && (
        <Home
          token={token}
          email={email}
          onLogout={handleLogout}
          onShowDeposit={() => setView("deposit")}
          onShowWithdraw={() => setView("withdraw")}
          onShowAdminDepositRequests={() => setView("adminDeposits")}
          onShowAdminWithdraw={() => setView("adminWithdraws")}
          onShowHistory={() => setView("userHistory")}
          onShowAdminUserHistory={() => setView("adminUserHistory")}
          onShowMatch={() => setView("match")} // ✅ নতুন ম্যাচ রাউট
        />
      )}

      {view === "deposit" && (
        <DepositForm token={token} onCancel={() => setView("home")} />
      )}

      {view === "withdraw" && (
        <WithdrawForm token={token} onCancel={() => setView("home")} />
      )}

      {view === "adminDeposits" && isAdmin && (
        <AdminDepositRequests onCancel={() => setView("home")} />
      )}

      {view === "adminWithdraws" && isAdmin && (
        <AdminWithdrawRequests onCancel={() => setView("home")} />
      )}

      {view === "userHistory" && (
        <UserHistory onCancel={() => setView("home")} />
      )}

      {view === "adminUserHistory" && isAdmin && (
        <AdminUserHistory onCancel={() => setView("home")} />
      )}

      {view === "match" && (
        <Match userEmail={email} /> // ✅ ম্যাচ কম্পোনেন্ট যুক্ত
      )}
    </div>
  );
}

export default App;
